using System.Security.Cryptography;using Microsoft.AspNetCore.Authentication.Cookies;using Microsoft.EntityFrameworkCore;using Indamin.Payment.Data;using Indamin.Payment.Services;
var b=WebApplication.CreateBuilder(args);b.Services.AddControllersWithViews();b.Services.AddDbContext<AppDbContext>(o=>o.UseSqlServer(b.Configuration.GetConnectionString("Default")));b.Services.AddScoped<ExcelService>();b.Services.AddScoped<PaymentCalculationService>();b.Services.AddDistributedMemoryCache();b.Services.AddSession(o=>{o.Cookie.HttpOnly=true;o.Cookie.IsEssential=true;o.IdleTimeout=TimeSpan.FromHours(4);});b.Services.AddAuthentication(CookieAuthenticationDefaults.AuthenticationScheme).AddCookie(o=>{o.LoginPath="/Account/Login";o.AccessDeniedPath="/Account/Denied";o.ExpireTimeSpan=TimeSpan.FromHours(8);o.SlidingExpiration=true;});b.Services.AddAuthorization(o=>o.AddPolicy("AdminOnly",p=>p.RequireClaim("IsAdmin","1")));
var app=b.Build();using(var sc=app.Services.CreateScope()){var db=sc.ServiceProvider.GetRequiredService<AppDbContext>();await DatabaseInitializer.InitializeAsync(db);await DatabaseInitializer.EnsureCompanySettingsAsync(db);await DatabaseInitializer.SeedAsync(db);var pwd=app.Configuration["InitialAdminPassword"];if(string.IsNullOrWhiteSpace(pwd))throw new InvalidOperationException("InitialAdminPassword باید تنظیم شود.");if(!await db.Users.AnyAsync(x=>x.IsAdmin)){db.Users.Add(new AppUser{UserName="admin",DisplayName="مدیر سامانه پرداخت",IsAdmin=true,IsActive=true,PasswordHash=PasswordHasher.Hash(pwd)});await db.SaveChangesAsync();}}
if(!app.Environment.IsDevelopment())app.UseExceptionHandler("/Home/Error");app.UseStaticFiles();app.UseRouting();app.UseSession();app.UseAuthentication();app.UseAuthorization();app.MapControllerRoute("default","{controller=Home}/{action=Index}/{id?}");app.Run();
public static class PasswordHasher{public static string Hash(string v){var s=RandomNumberGenerator.GetBytes(16);var k=Rfc2898DeriveBytes.Pbkdf2(v,s,100000,System.Security.Cryptography.HashAlgorithmName.SHA256,32);return $"100000.{Convert.ToBase64String(s)}.{Convert.ToBase64String(k)}";}public static bool Verify(string v,string st){try{var p=st.Split('.');if(p.Length!=3)return false;var s=Convert.FromBase64String(p[1]);var e=Convert.FromBase64String(p[2]);var k=Rfc2898DeriveBytes.Pbkdf2(v,s,int.Parse(p[0]),System.Security.Cryptography.HashAlgorithmName.SHA256,e.Length);return CryptographicOperations.FixedTimeEquals(k,e);}catch{return false;}}}
